@startuml

class User {
  + fullName : string
}

class UnderAgedUser extends User {
  + studentCard : string
}

class AdultUser extends User {
  + idCard : string
}

class Book {
  + title : string
  + author : string
}

class BorrowHistory {
  + date : date
}

User "1" -- "0..4" Book : borrows
User "1" -- "*" BorrowHistory : has
BorrowHistory "*" -- "1" Book : for

@enduml

